1	package checkpoint
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"log/slog"
8	
9		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
10		"github.com/entireio/cli/cmd/entire/cli/logging"
11	)
12	
13	// CommittedReader provides read access to committed checkpoint data.
14	// Both GitStore (v1) and V2GitStore (v2) implement this interface.
15	type CommittedReader interface {
16		ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error)
17		ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)
18	}
19	
20	// CommittedListReader provides read and list access to committed checkpoint data.
21	// GitStore, V2GitStore, and DualCheckpointReader implement this interface.
22	type CommittedListReader interface {
23		CommittedReader
24		ListCommitted(ctx context.Context) ([]CommittedInfo, error)
25		ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*CommittedMetadata, error)
26	}
27	
28	type CommittedReadMode int
29	
30	const (
31		CommittedReadV1 CommittedReadMode = iota
32		CommittedReadDual
33		CommittedReadV2
34	)
35	
36	func CommittedReadModeForOptions(checkpointsV2Enabled bool, checkpointsVersion int) CommittedReadMode {
37		if checkpointsVersion == 2 {
38			return CommittedReadV2
39		}
40		if checkpointsV2Enabled {
41			return CommittedReadDual
42		}
43		return CommittedReadV1
44	}
45	
46	func NewCommittedReader(v1Store *GitStore, v2Store *V2GitStore, mode CommittedReadMode) (CommittedListReader, error) {
47		switch mode {
48		case CommittedReadV2:
49			if v2Store == nil {
50				return nil, errors.New("v2 committed checkpoint reader unavailable")
51			}
52			return v2Store, nil
53		case CommittedReadDual:
54			if v2Store == nil {
55				if v1Store == nil {
56					return nil, errors.New("committed checkpoint reader unavailable")
57				}
58				return v1Store, nil
59			}
60			if v1Store == nil {
61				return v2Store, nil
62			}
63			return &DualCheckpointReader{v2: v2Store, v1: v1Store}, nil
64		case CommittedReadV1:
65			if v1Store == nil {
66				return nil, errors.New("v1 committed checkpoint reader unavailable")
67			}
68			return v1Store, nil
69		default:
70			return nil, fmt.Errorf("unknown committed checkpoint read mode: %d", mode)
71		}
72	}
73	
74	type DualCheckpointReader struct {
75		v2 *V2GitStore
76		v1 *GitStore
77	}
78	
79	func (r *DualCheckpointReader) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
80		summary, err := r.v2.ReadCommitted(ctx, checkpointID)
81		if err == nil && summary != nil {
82			return summary, nil
83		}
84		if ctxErr := ctx.Err(); ctxErr != nil {
85			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
86		}
87		if err != nil {
88			logV2Fallback(ctx, "v2 ReadCommitted failed, falling back to v1", checkpointID, err)
89		}
90		return r.v1.ReadCommitted(ctx, checkpointID)
91	}
92	
93	func (r *DualCheckpointReader) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
94		content, err := r.v2.ReadSessionContent(ctx, checkpointID, sessionIndex)
95		if err == nil {
96			return content, nil
97		}
98		if ctxErr := ctx.Err(); ctxErr != nil {
99			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
100		}
101		if errors.Is(err, ErrNoTranscript) {
102			fallbackContent, fallbackErr := r.readFallbackSessionContent(ctx, checkpointID, sessionIndex)
103			if fallbackErr == nil {
104				return fallbackContent, nil
105			}
106			if ctxErr := ctx.Err(); ctxErr != nil {
107				return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
108			}
109			return nil, err
110		}
111		return r.readV1SessionContentByIndex(ctx, checkpointID, sessionIndex, err)
112	}
113	
114	func (r *DualCheckpointReader) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*CommittedMetadata, error) {
115		metadata, err := r.v2.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
116		if err == nil {
117			return metadata, nil
118		}
119		if ctxErr := ctx.Err(); ctxErr != nil {
120			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
121		}
122		return r.readV1SessionMetadataByIndex(ctx, checkpointID, sessionIndex, err)
123	}
124	
125	// ReadSessionMetadataAndPrompts is intentionally v2-only because callers pair
126	// this metadata with the v2 compact transcript. Returning v1 raw content here
127	// would bypass the checkpoint transcript offset handling in ReadSessionContent.
128	func (r *DualCheckpointReader) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
129		return r.v2.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
130	}
