func NewCommittedReader(v1Store *GitStore, v2Store *V2GitStore, mode CommittedReadMode) (CommittedListReader, error) {
	switch mode {
	case CommittedReadV2:
		if v2Store == nil {
			return nil, errors.New("v2 committed checkpoint reader unavailable")
