	case CommittedReadDual:
		switch {
		case v2Store == nil && v1Store == nil:
			return nil, errors.New("committed checkpoint reader unavailable")
		case v2Store == nil:
			return v1Store, nil
		case v1Store == nil:
			return v2Store, nil
		default:
			return &DualCheckpointReader{v2: v2Store, v1: v1Store}, nil
		}
	case CommittedReadV1:
		if v1Store == nil {
			return nil, errors.New("v1 committed checkpoint reader unavailable")
		}
		return v1Store, nil
	default:
		return nil, fmt.Errorf("unknown committed checkpoint read mode: %d", mode)
	}
}

// preferCtxErr returns ctx.Err() when the context has been cancelled, otherwise
// returns the supplied fallback error. Lets DualCheckpointReader collapse the
// repeated "if context done, surface that; else propagate the original" tail
// after each v2 read into a single call.
func preferCtxErr(ctx context.Context, fallback error) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	return fallback
}

