	if err == nil {
		return metadata, nil
	}
	if ctxErr := ctx.Err(); ctxErr != nil {
		return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
	}
	return r.readV1SessionMetadataByIndex(ctx, checkpointID, sessionIndex, err)
